// Object
// ------

import { assignOwn } from '../utils/assign-in.js';
import extend from '../utils/extend.js';
import uniqueId from '../utils/unique-id.js';
import CommonMixin from '../mixins/common.js';
import DestroyMixin from '../mixins/destroy.js';
import RadioMixin from '../mixins/radio.js';

const ClassOptions = [
  'channelName',
  'radioEvents',
  'radioRequests'
];

// Object borrows many conventions and utilities from Backbone.
const MarionetteObject = function(options) {
  this._setOptions(options, ClassOptions);
  this.cid = uniqueId(this.cidPrefix);
  this._initRadio();
  this.initialize.apply(this, arguments);
};

MarionetteObject.extend = extend;

// Object Methods
// --------------

assignOwn(MarionetteObject.prototype, CommonMixin, DestroyMixin, RadioMixin, {
  cidPrefix: 'mno',
});

export default MarionetteObject;
